method Strongest_Extension(class_name: string, extensions: seq<string>) returns (result: string)
    requires class_name != ""
    requires extensions != []
    requires forall ext: string :: ext in extensions ==> ext != ""
    ensures result == class_name + "." + (strongestExtension(extensions))
{
    var strongest := extensions[0];
    var max_strength := calculate_strength(strongest);

    var i := 1;
    while i < |extensions|
        invariant 0 <= i <= |extensions|
        invariant forall j: int :: 0 <= j < i ==> calculate_strength(extensions[j]) <= max_strength
    {
        var current := extensions[i];
        var current_strength := calculate_strength(current);
        if current_strength > max_strength {
            strongest := current;
            max_strength := current_strength;
        }
        i := i + 1;
    }

    result := class_name + "." + strongest;
}

method calculate_strength(extension: string) returns (strength: int)
{
    var CAP := 0;
    var SM := 0;

    var i := 0;
    while i < |extension|
        invariant 0 <= i <= |extension|
        invariant CAP >= 0 && SM >= 0
    {
        if extension[i] >= 'A' && extension[i] <= 'Z' {
            CAP := CAP + 1;
        } else if extension[i] >= 'a' && extension[i] <= 'z' {
            SM := SM + 1;
        }
        i := i + 1;
    }
    strength := CAP - SM;
}
